import{_ as e,o as a,c as t,a2 as r}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"LocalSend 局域网传输设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/localsend.md","filePath":"zh-CN/user-guide/settings/localsend.md","lastUpdated":1787586465000}'),n={name:"zh-CN/user-guide/settings/localsend.md"};function l(s,o,i,d,c,g){return a(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="localsend-局域网传输设置" tabindex="-1">LocalSend 局域网传输设置 <a class="header-anchor" href="#localsend-局域网传输设置" aria-label="Permalink to &quot;LocalSend 局域网传输设置&quot;">​</a></h1><p>Lertaro 内置了与官方开源 <a href="https://localsend.org" target="_blank" rel="noreferrer">LocalSend</a> 协议原生兼容的局域网无线传输引擎。无需依赖外部互联网或数据线，即可在同一局域网下的 Windows 电脑、Mac、Linux、iPhone、iPad 以及 Android 手机之间极速互传文件、文件夹与纯文本。设置页面路径为<strong>设置 → LocalSend</strong>。</p><h2 id="_1-基础服务设置" tabindex="-1">1. 基础服务设置 <a class="header-anchor" href="#_1-基础服务设置" aria-label="Permalink to &quot;1. 基础服务设置&quot;">​</a></h2><ul><li><strong>启用 LocalSend 局域网传输</strong>：总开关。开启后，Lertaro 会在后台启动轻量级传输监听服务，并在系统托盘菜单中激活“发送到其他设备...”功能项。</li><li><strong>设备名称</strong>：本机在局域网多播广播中向其他设备展示的别名。默认根据计算机名称自动生成，你可以随时修改为一个更具辨识度的名称（例如 <code>工作笔记本</code>）。</li><li><strong>服务端口</strong>：HTTP / HTTPS 传输监听端口（遵循 LocalSend 官方标准，默认为 <code>53317</code>）。若本地该端口被其他服务占用，可在此自定义更改。</li></ul><h2 id="_2-安全加密与存储规则" tabindex="-1">2. 安全加密与存储规则 <a class="header-anchor" href="#_2-安全加密与存储规则" aria-label="Permalink to &quot;2. 安全加密与存储规则&quot;">​</a></h2><ul><li><strong>加密传输 (HTTPS)</strong>：默认开启。启用后设备间的数据往来均采用 TLS 加密传输，防止局域网抓包窥探。</li><li><strong>接收 PIN 码</strong>：可设置 4–6 位数字 PIN 码。设置后，其他设备向你发起传输请求时必须在发送端输入匹配的 PIN 码方可建立连接（留空则不开启验证）。</li><li><strong>自动保存文件</strong>：开启后，接收来自局域网设备的传输请求将自动确认并下载落盘，无需每次手动点击弹窗确认。</li><li><strong>保存目录</strong>：设置接收到的文件与文件夹默认保存的物理目标路径（默认保存在用户系统的 <code>Downloads\\LocalSend</code> 目录下），点击右侧浏览按钮可随时更改。</li></ul><h2 id="_3-发送窗口与快捷调用" tabindex="-1">3. 发送窗口与快捷调用 <a class="header-anchor" href="#_3-发送窗口与快捷调用" aria-label="Permalink to &quot;3. 发送窗口与快捷调用&quot;">​</a></h2><ul><li><strong>快捷键唤起</strong>：可在全局任何界面按下默认快捷键 <strong><code>Ctrl+S</code></strong>（可在<a href="./hotkeys-page.html"><strong>设置 → 热键</strong></a>中重新绑定）瞬间唤起 LocalSend 独立发送窗口。</li><li><strong>发送模式切换</strong>：发送窗口顶部支持在 <strong>[发送文件 / 文件夹]</strong> 与 <strong>[发送文本]</strong> 两种模式之间一键切换。</li><li><strong>即时拖拽分发</strong>：支持直接从 Lertaro 搜索结果列表、快速面板或文件资源管理器中将多个文件或整个项目目录拖入发送窗口，雷达扫描会自动列出局域网内当前在线的所有设备，点击目标设备头像即可全速发送。</li></ul>',8)])])}const u=e(n,[["render",l]]);export{_ as __pageData,u as default};
